public class Main {
    static int sumTo(int n) {
        int total = 0;
        for (int i = 1; i <= n; i++) {
            total += i;
        }
        return total;
    }

    public static void main(String[] args) {
        System.out.println(sumTo(5));
    }
}

task.solution:
public class Main {
    static int sumTo(int n) {
        if (n <= 1) {
            return n;
        }
        return n + sumTo(n - 1);
    }

    static int sumTo(int from, int to) {
        return sumTo(to) - sumTo(from - 1);
    }

    public static void main(String[] args) {
        System.out.println(sumTo(5) + " " + sumTo(3, 5));
    }
}

